WITH valid AS (SELECT id, store_id, product_id, quantity, last_restock, CAST(quantity AS STRING) AS quantity_num FROM inventory WHERE last_restock >= TO_DATE('2023-03-18') AND last_restock >= '2025-07-01') SELECT id, store_id, last_restock, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY last_restock DESC, id) AS row_seq, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY quantity, id) AS event_seq, SUM(quantity) OVER (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity, NTILE(10) OVER (PARTITION BY store_id, product_id ORDER BY quantity DESC, id) AS quantity_bucket FROM valid WHERE last_restock >= '2024-02-01';
